//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF39003.xml";
scwin.gLastJob = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


//저장버튼 클릭 시
scwin.fn_Save = function() {
    //dts_MASTER.AddRow();
    //dts_MASTER.NameValue(1,"MKT_TP_CD") =  getObjectValue(rdo_mkt_tp_cd); 	//  js_market;		시장구분

    var mkt_tp_cd = $c.stf.getObjectValue(rdo_mkt_tp_cd);
    var mkt_tp_nm = "";
    var confirmGbn = "";
    if ($c.stf.getObjectValue(txb_FILE) == '') {
        $c.win.alert("[첨부파일]을 선택하세요.");
        file.focus();
        return;
    }
    if (mkt_tp_cd == "1") {
        mkt_tp_nm = "유가";
    } else if (mkt_tp_cd == "2") {
        mkt_tp_nm = "코스닥";
    } else if (mkt_tp_cd == "6") {
        mkt_tp_nm = "코넥스";
    } else if (mkt_tp_cd == "9") {
        mkt_tp_nm = "전체";
    }
    if (js_market == "9") {
        confirmGbn = "시장구분이 '" + mkt_tp_nm + "' 입니다.\n기존 '" + mkt_tp_nm + "' 데이터가 삭제 된 후 첨부한 데이터가 업로드 됩니다.\n파일 업로드 하시겠습니까?";
    } else {
        confirmGbn = "기존 '" + mkt_tp_nm + "' 데이터가 삭제 된 후 첨부한 데이터가 업로드 됩니다.\n파일 업로드 하시겠습니까?";
    }
    if (confirm(confirmGbn)) {
        scwin.gLastJob = "파일 업로드";
        trs_Save.Action = "/OutDir.do?method=saveOutsideExcelUpload" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&mkt_tp_cd=" + mkt_tp_cd;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_MASTER,I:pFile=dts_FileList)";
        trs_Save.Post();
    }
};




// 저장 에러 발생 시
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};





//파일첨부 버튼 클릭 시
scwin.fn_SelectAttach = function() {
    var vFile = file.getValue();
    if (vFile == "") {
        return;
    } else if (vFile.substring(vFile.length - 3, vFile.length).toUpperCase() != "XLS") {
        $c.win.alert("엑셀파일(*.xls)만 입력하시기 바랍니다.");
        txb_FILE.setValue("");
        return;
    } else {
        txb_FILE.setValue(file.getValue());
        dts_FileList.setCellData(1, "fileInfo", file.getValue());
        dts_FileList.setCellData(1, "fileUrl", file.getValue());
    }
};





// 초기화
scwin.fn_Init = function() {
    //파일업로드 데이터셋 초기화

    //dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_FileList.insertRow();
    $c.stf.setObjectValue(rdo_mkt_tp_cd, js_market);
    if (js_market == "9") {
        rdo_mkt_tp_cd.setDisabled(false);
        rdo_mkt_tp_cd.addClass("TopCondition_Blue");
        $c.stf.showObj(txb_mkt_nm, false);
    } else {
        // 콘트롤 잠그기
        //grd_Grid.ColumnProp("MKT_NM", "Show") = false;
        //rdo_mkt_tp_cd.Enable = false;
        $c.stf.showObj(rdo_mkt_tp_cd, false);
        $c.stf.showObj(txb_mkt_nm, true);
        if ($c.stf.getObjectValue(rdo_mkt_tp_cd) == "1") {
            $c.stf.setObjectValue(txb_mkt_nm, "유가");
        } else if ($c.stf.getObjectValue(rdo_mkt_tp_cd) == "2") {
            $c.stf.setObjectValue(txb_mkt_nm, "코스닥");
        } else if ($c.stf.getObjectValue(rdo_mkt_tp_cd) == "6") {
            $c.stf.setObjectValue(txb_mkt_nm, "코넥스");
        }
    }
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    scwin.alert_error2(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    await $c.frame.CloseFrame();
    $c.frame.path("../").fn_Search();
};
scwin.file_OnClick = function() {
    scwin.fn_SelectAttach();
};
scwin.btn_FORM_DOWN_onclick = function() {
    location.href = "/dsclmgt/outside_upload_sample.xls";
};
scwin.gform_onload = function() {
    //frame.width = 580;
    //frame.height = 240;

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_Init();
};
scwin.rdo_mkt_tp_cd_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
